head.script:
///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 화면을 초기화한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00306.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name grd_ForncurrAsstDebt_oncelldblclick
 * @description 팝업분기 — 외화자산 컬럼 더블클릭 시 외화자산 팝업, 외화부채 컬럼 더블클릭 시 외화부채 팝업을 오픈한다.
 * @param {Number} rowIndex 더블클릭한 행 인덱스
 * @param {Number} columnIndex 더블클릭한 컬럼 인덱스
 * @param {String} columnId 더블클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_ForncurrAsstDebt_oncelldblclick(0, 0, "valuBas1");
 */
scwin.grd_ForncurrAsstDebt_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        if (columnId === "valuBas1") {
            // 외화자산  팝업 오픈
            scwin.forncurrAsstSrchOpen(rowIndex);
        } else if (columnId === "valuBas2") {
            // 외화부채 팝업 오픈
            scwin.forncurrDebtSrchOpen(rowIndex);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00306.grd_ForncurrAsstDebt_oncelldblclick" });
    }
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {void}
 * @hidden N
 * @example scwin.init();
 */
scwin.init = function() {
    scwin.search();
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 * @example scwin.initDs();
 */
scwin.initDs = function() {
    dlt_ForncurrAsstDebtRes.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {Boolean} 유효성 체크 결과
 * @hidden N
 * @example if (!scwin.chkValid()) { return; }
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    scwin.vKisCd = $p.parent().wfm_header.getWindow().scwin.fn_GetKisCd();
    if (scwin.vKisCd === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description 외화자산/부채 조회
 * @returns {void}
 * @hidden N
 * @example scwin.search();
 */
scwin.search = function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();

    const url = "/api/listing/nice/individual-notes/" + ibxKisCd + "/foreign-currency";
    $c.sbm.setAction(sbm_dlt_ForncurrAsstDebt, url);
    $c.sbm.execute(sbm_dlt_ForncurrAsstDebt);
};

/**
 * @method
 * @name forncurrAsstSrchOpen
 * @description 외화자산  팝업
 * @param {Number} pRow 대상 행 인덱스
 * @returns {void}
 * @hidden N
 * @example scwin.forncurrAsstSrchOpen(0);
 */
scwin.forncurrAsstSrchOpen = function(pRow) {
    console.log(pRow);
    const url = "/ui/lst/fis/ULDFIS00300_P3.xml";
    const popTitle = "외화자산 검색";

    const opts = {
        id: "ULDFIS00300_P3",
        popupName: popTitle,
        width: 700,
        height: 500,
        frameModal: "top",
    };

    const popData = dlt_ForncurrAsstDebtRes.getRowJSON(pRow);
    $c.win.openPopup(url, opts, popData);
};

/**
 * @method
 * @name forncurrDebtSrchOpen
 * @description 외화부채  팝업
 * @param {Number} pRow 대상 행 인덱스
 * @returns {void}
 * @hidden N
 * @example await scwin.forncurrDebtSrchOpen(0);
 */
scwin.forncurrDebtSrchOpen = async function(pRow) {
    console.log(pRow);
    const url = "/ui/lst/fis/ULDFIS00300_P4.xml";
    const popTitle = "외화부채 검색";

    const opts = {
        id: "ULDFIS00300_P4",
        popupName: popTitle,
        width: 700,
        height: 590,
        frameModal: "top",
    };

    const popData = dlt_ForncurrAsstDebtRes.getRowJSON(pRow);
    console.log("rowData :: "  + popData);
    $c.win.openPopup(url, opts, popData);
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {void}
 * @hidden N
 * @example scwin.excelDownload();
 */
scwin.excelDownload = function() {
    if (dlt_ForncurrAsstDebtRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_ForncurrAsstDebt, {fileName: "외화자산부채", type: "8"});
};

/**
 * @method
 * @name gform_onload
 * @description 구 gform 온로드 핸들러 — 화면 초기화를 호출한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = function() {
    scwin.init();
};
